/// Persist a user override to app_config_dir/config.json. Empty/invalid fields fall back to current config.
#[tauri::command]
fn save_config(
    app: AppHandle,
    api_base_url: Option<String>,
    refresh_interval_minutes: Option<u64>,
    default_section: Option<String>,
    items_per_section: Option<u64>,
) -> Result<AppConfig, String> {
    let current = load_config(&app);
    let next = AppConfig {
        api_base_url: api_base_url
            .map(|s| s.trim().trim_end_matches('/').to_string())
            .filter(|s| !s.is_empty())
            .unwrap_or(current.api_base_url),
        refresh_interval_minutes: refresh_interval_minutes
            .filter(|n| *n >= 5)
            .unwrap_or(current.refresh_interval_minutes),
        default_section: default_section
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .unwrap_or(current.default_section),
        items_per_section: items_per_section
            .filter(|n| *n > 0)
            .unwrap_or(current.items_per_section),
    };

    let dir = app.path().app_config_dir().map_err(|e| e.to_string())?;
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let payload = serde_json::json!({
        "apiBaseUrl": next.api_base_url,
        "refreshIntervalMinutes": next.refresh_interval_minutes,
        "defaultSection": next.default_section,
        "itemsPerSection": next.items_per_section,
    });
    fs::write(dir.join("config.json"), payload.to_string()).map_err(|e| e.to_string())?;
    Ok(next)
}

